insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order)
values ('gold-digger', 'Can it place trades on my broker account?', 'Yes, through a MetaTrader 5 account at any broker, including XM, but not by default. The connection starts read-only and the app trades on a paper account. Sending real orders needs you to enable order commands, choose MT5 as the venue and, for a live account, unlock live trading with a typed confirmation every session. Every order must still pass the risk engine.', 'Broker connection', null, true, 2);

insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order)
values ('gold-digger', 'Do I need a broker account to try it?', 'No. It opens on simulated data with a paper account, and everything works without a MetaTrader 5 terminal.', 'Getting started', null, true, 3);

insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order)
values ('gold-digger', 'Why does Windows warn me about the installer?', 'The installer is not yet code-signed, so Windows shows an unknown-publisher warning. Before choosing More info and Run anyway, compare the SHA-256 checksum of your download with the one shown on this site. If they differ, do not run the file.', 'Installation', null, true, 4);

insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order)
values ('gold-digger', 'Why does it reject almost every trade on my small account?', 'On a standard gold contract the smallest position can risk more than the limits allow on a small balance, so the risk engine refuses. That is intended. The app shows how much the broker''s contract needs under Trading, Can it trade now.', 'Risk', null, true, 5);

insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order)
values ('gold-digger', 'Where does the market data come from?', 'Prices come from your MetaTrader 5 terminal, or from a built-in simulator when no broker is connected. Macro data comes from FRED, news from RSS feeds, and the economic calendar from a public weekly export.', 'Data', null, true, 6);

